function renderRttStandalone(d){
 const aq=(d&&d.aq)||state.files.AQ?.rows||[];
 const r=analyzeRtt(aq);
 const metrics=$("rttMetrics"),count=$("rttCount"),body=document.querySelector("#rttTable tbody");
 if(metrics)metrics.innerHTML=[
 ["HIGH CLIENT RTT",fmt(r.highClient),"records >100 ms","var(--amber)"],
 ["HIGH SERVER RTT",fmt(r.highServer),"records >100 ms","var(--red)"],
 ["TOTAL HIGH RTT",fmt(r.highRows.length),"unique non-DNS records","var(--cyan)"],
 ["MAX CLIENT / SERVER",fmt(r.maxClient)+" / "+fmt(r.maxServer)+" ms","maximum observed RTT","var(--muted)"],
 ["DATA COVERAGE",fmt(r.baseCount)+" non-DNS",fmt(r.validClient)+" Client / "+fmt(r.validServer)+" Server valid","var(--cyan)"]
 ].map(x=>'<div class="kpi"><div class="kpi-label">'+esc(x[0])+'</div><div class="kpi-value" style="color:'+x[3]+'">'+esc(x[1])+'</div><div class="kpi-note">'+esc(x[2])+'</div></div>').join("");
 if(body){
  body.innerHTML=r.highRows.length?r.highRows.map(x=>{
   const row=x.row,flags=[x.client!==null&&x.client>100?"High Client RTT":"",x.server!==null&&x.server>100?"High Server RTT":""].filter(Boolean).join(" + ");
   return '<tr><td>'+esc(dateShort(val(row,"Start Time")))+'</td><td>'+esc(val(row,"APP Name"))+'</td><td class="num">'+(x.client===null?"—":fmt(x.client))+'</td><td class="num">'+(x.server===null?"—":fmt(x.server))+'</td><td>'+esc(val(row,"Site Name","Serving Site"))+'</td><td class="cell">'+esc(val(row,"Last Cell Name","Cell Name"))+'</td><td><span class="tag amber">'+esc(flags)+'</span></td></tr>';
  }).join(""):'<tr><td class="empty" colspan="7">Tidak ada record >100 ms. Kolom terdeteksi: '+esc(r.clientKey||"NOT FOUND")+' / '+esc(r.serverKey||"NOT FOUND")+'. Nilai valid: '+r.validClient+' / '+r.validServer+'.</td></tr>';
 }
 if(count)count.textContent="Client >100 ms: "+r.highClient+" · Server >100 ms: "+r.highServer+" · unik: "+r.highRows.length+" · valid: "+r.validClient+"/"+r.validServer+" · DNS dikecualikan: "+r.dnsExcluded+" · kolom: "+(r.clientKey||"NOT FOUND")+" / "+(r.serverKey||"NOT FOUND");
 const search=$("rttSearch");
 if(search)search.oninput=()=>{const q=search.value.toLowerCase();const filtered=r.highRows.filter(x=>Object.values(x.row).join(" ").toLowerCase().includes(q));if(body)body.innerHTML=filtered.map(x=>{const row=x.row,flags=[x.client!==null&&x.client>100?"High Client RTT":"",x.server!==null&&x.server>100?"High Server RTT":""].filter(Boolean).join(" + ");return '<tr><td>'+esc(dateShort(val(row,"Start Time")))+'</td><td>'+esc(val(row,"APP Name"))+'</td><td class="num">'+(x.client===null?"—":fmt(x.client))+'</td><td class="num">'+(x.server===null?"—":fmt(x.server))+'</td><td>'+esc(val(row,"Site Name","Serving Site"))+'</td><td class="cell">'+esc(val(row,"Last Cell Name","Cell Name"))+'</td><td>'+esc(flags)+'</td></tr>'}).join("")||'<tr><td class="empty" colspan="7">Tidak ada hasil pencarian.</td></tr>';if(count)count.textContent=filtered.length+" / "+r.highRows.length+" high RTT records"};
 try{chart("rttChart","bar",["High Client RTT","High Server RTT"],[{label:"Records >100 ms",data:[r.highClient,r.highServer],backgroundColor:["#ffbd5c","#ff727c"],borderRadius:4}],{plugins:{legend:{display:false}}})}catch(e){console.warn("RTT chart skipped; KPI and table remain available",e)}
 window.__telecomRttDebug={clientKey:r.clientKey,serverKey:r.serverKey,totalAQ:aq.length,dnsExcluded:r.dnsExcluded,validClient:r.validClient,validServer:r.validServer,highClient:r.highClient,highServer:r.highServer,highUnique:r.highRows.length};
}
window.renderAll=renderAll;
const __renderAllBase=window.renderAll;
window.renderAll=function(d){
 let baseError=null;
 try{__renderAllBase(d)}catch(e){baseError=e;console.error("Base dashboard render error",e)}
 try{
  const r=analyzeRtt((d&&d.aq)||state.files.AQ?.rows||[]);
  const metrics=document.getElementById("rttMetrics"),count=document.getElementById("rttCount"),body=document.querySelector("#rttTable tbody");
  if(metrics)metrics.innerHTML=[
   ["HIGH CLIENT RTT",r.highClient,"records >100 ms","var(--amber)"],
   ["HIGH SERVER RTT",r.highServer,"records >100 ms","var(--red)"],
   ["TOTAL HIGH RTT",r.highRows.length,"distinct non-DNS records","var(--cyan)"],
   ["MAX CLIENT / SERVER",fmt(r.maxClient)+" / "+fmt(r.maxServer)+" ms","maximum valid non-DNS RTT","var(--muted)"],
   ["DATA COVERAGE",fmt(r.baseCount)+" non-DNS",fmt(r.validClient)+" client / "+fmt(r.validServer)+" server valid","var(--cyan)"]
  ].map(x=>'<div class="kpi"><div class="kpi-label">'+x[0]+'</div><div class="kpi-value" style="color:'+x[3]+'">'+x[1]+'</div><div class="kpi-note">'+x[2]+'</div></div>').join("");
  const draw=arr=>{if(!body)return;body.innerHTML=arr.length?arr.map(x=>{const row=x.row,flag=[x.client!==null&&x.client>100?"High Client RTT":"",x.server!==null&&x.server>100?"High Server RTT":""].filter(Boolean).join(" + ");return '<tr><td>'+esc(dateShort(val(row,"Start Time")))+'</td><td>'+esc(val(row,"APP Name"))+'</td><td class="num">'+(x.client===null?"—":fmt(x.client))+'</td><td class="num">'+(x.server===null?"—":fmt(x.server))+'</td><td>'+esc(val(row,"Site Name","Serving Site"))+'</td><td class="cell">'+esc(val(row,"Last Cell Name","Cell Name"))+'</td><td><span class="tag amber">'+esc(flag)+'</span></td></tr>'}).join(""):'<tr><td class="empty" colspan="7">Tidak ada record >100 ms. Kolom terdeteksi: '+esc(r.clientKey||"Client tidak ditemukan")+' / '+esc(r.serverKey||"Server tidak ditemukan")+'. Nilai valid: '+r.validClient+' / '+r.validServer+'.</td></tr>'};
  draw(r.highRows);
  const status="Client >100 ms: "+r.highClient+" · Server >100 ms: "+r.highServer+" · total unik: "+r.highRows.length+" · valid: "+r.validClient+"/"+r.validServer+" · DNS dikecualikan: "+r.dnsExcluded+" · kolom: "+(r.clientKey||"NOT FOUND")+" / "+(r.serverKey||"NOT FOUND");
  if(count)count.textContent=status+(baseError?" · render warning: "+baseError.message:"");
  const search=document.getElementById("rttSearch");
  if(search){search.oninput=()=>{const q=search.value.toLowerCase();draw(r.highRows.filter(x=>Object.values(x.row).join(" ").toLowerCase().includes(q)));if(count)count.textContent=status+" · filtered "+(r.highRows.filter(x=>Object.values(x.row).join(" ").toLowerCase().includes(q)).length)+"/"+r.highRows.length;};}
  try{chart("rttChart","bar",["High Client RTT","High Server RTT"],[{label:"Records >100 ms",data:[r.highClient,r.highServer],backgroundColor:["#ffbd5c","#ff727c"],borderRadius:4}],{plugins:{legend:{display:false}}})}catch(chartErr){console.warn("RTT chart unavailable",chartErr)}
  window.__telecomRttDebug={clientKey:r.clientKey,serverKey:r.serverKey,validClient:r.validClient,validServer:r.validServer,highClient:r.highClient,highServer:r.highServer,highRows:r.highRows.length,dnsExcluded:r.dnsExcluded};
 }catch(e){console.error("RTT render failed",e);const c=document.getElementById("rttCount");if(c)c.textContent="RTT render error: "+e.message;const b=document.querySelector("#rttTable tbody");if(b)b.innerHTML='<tr><td class="empty" colspan="7">RTT render error: '+esc(e.message)+'</td></tr>'}
};
window.__telecomShowTab=function(name){document.querySelectorAll(".tab").forEach(x=>{const active=x.dataset.tab===name;x.classList.toggle("active",active);x.setAttribute("aria-selected",active?"true":"false")});document.querySelectorAll(".tabpage").forEach(x=>x.classList.toggle("hidden",x.id!=="tab-"+name));if(name!=="data"&&window.__telecomMapInvalidate)setTimeout(window.__telecomMapInvalidate,100)};document.querySelectorAll(".tab").forEach(b=>b.addEventListener("click",()=>window.__telecomShowTab(b.dataset.tab)));